function fitNavigation(){if(mobile.matches&&!$('#app').classList.contains('collapsed'))$('#nav-toggle').click();}
mobile.addEventListener('change',fitNavigation);fitNavigation();
window.addEventListener('hashchange',()=>{if(state.data)render();});$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog'))$('#dialog').close();});
(async()=>{try{await signedIn(await api('/api/me'));}catch(error){$('#app').hidden=true;$('#signin').hidden=false;}})();
